using System.Collections;
using System.Collections.Generic;
using Astrea.BattleActions;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AreaPurifyCorruptEffect", menuName = "Data/Battle/Effects/Area Purify Corrupt Effect")]
public class AreaPurifyCorruptEffect : Effect
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	[SerializeField]
	private bool corruptEffect;

	[Header("VFX Animation")]
	[SerializeField]
	private float delayToVFX = 0.2f;

	[SerializeField]
	private float delayToDealCorruptPurify = 1f;

	[SerializeField]
	private bool useSecondVFXOnActivation;

	[Header("Radiant Bomb")]
	[SerializeField]
	private bool radiantBomb;

	[Header("Wave")]
	[SerializeField]
	private bool wave;

	[SerializeField]
	[ShowIf("wave")]
	private TriggerEffectAction waveCrasherAction;

	[SerializeField]
	[ShowIf("wave")]
	private AchievementData waveBenderAchievementData;

	[Header("Battle Action for Purify Corrupt SFX")]
	[SerializeField]
	private BattleAction battleAction;

	public bool RadiantBomb => radiantBomb;

	public bool Wave => wave;

	public BattleAction BattleAction => battleAction;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = (wave ? Smart.Format(GetLocalizedDescription(), battleAction.GetActionDescription(amount).RemoveLast(), base.localizationManager.GetLocalizedThenEnemyLoseAllEffect(this)) : (radiantBomb ? Smart.Format(GetLocalizedDescription(), battleAction.GetActionDescription(amount)) : Smart.Format(base.localizationManager.GetLocalizedWhenEnemyDefeatedBase(), battleAction.GetActionDescription(amount))));
		return text + AppendedDescription();
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (wave)
		{
			CheckWaveTrigger(effectAmount, effectOwner);
		}
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (wave)
		{
			CheckWaveTrigger(effectAmount, effectOwner);
		}
	}

	public void CheckWaveTrigger(int effectAmount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptedAnimalEffects>().WaveActivated)
		{
			float currentCorruption = effectOwner.GetComponent<CorruptionStats>().CurrentCorruption;
			if ((float)effectAmount >= currentCorruption)
			{
				effectOwner.GetComponent<CorruptedAnimalEffects>().WaveActivated = true;
				EnqueueAreaPurifyCorruptCoroutine(effectAmount, effectOwner);
			}
		}
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (wave && effectOwner.GetComponent<CorruptedAnimalEffects>().WaveActivated)
		{
			return effectAmount;
		}
		EnqueueAreaPurifyCorruptCoroutine(effectAmount, effectOwner);
		return effectAmount;
	}

	private void EnqueueAreaPurifyCorruptCoroutine(int effectAmount, GameObject effectOwner)
	{
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueCompanionAndEnemyDefeatAction(AreaPurifyCorruptCoroutine(effectAmount, effectOwner));
		instance.SetState(instance.ActionsQueueState);
	}

	public override int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
	{
		if (wave)
		{
			UnitEffects component = effectOwner.GetComponent<UnitEffects>();
			component.IsEffectActive(this);
			List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
			int num = effectAmount;
			if (waveCrasherAction.UseHalfOfTheEffect)
			{
				num = Mathf.CeilToInt((float)num / 2f);
			}
			if (useSecondVFXOnActivation)
			{
				if (IsSecondVFXEnabled())
				{
					SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 5f);
					PlayEffectActivationSFX();
				}
			}
			else if (IsVFXEnabled())
			{
				SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
				PlayEffectActivationSFX();
			}
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i] != null)
				{
					list[i].GetComponent<CorruptionStats>().Purify(num, null);
				}
			}
			if (battleAction != null)
			{
				battleAction.PlaySFX();
			}
			if (waveCrasherAction.DecreaseEffect)
			{
				component.IsEffectActiveAndDecreaseEffect(this, waveCrasherAction.DecreaseEffectAmount);
			}
		}
		else
		{
			GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
			instance.ActionsQueueState.EnqueueCompanionAndEnemyDefeatAction(AreaPurifyCorruptCoroutine(effectAmount, effectOwner));
			instance.SetState(instance.ActionsQueueState);
		}
		return effectAmount;
	}

	private IEnumerator AreaPurifyCorruptCoroutine(int effectAmount, GameObject effectOwner)
	{
		bool flag = false;
		if (radiantBomb && !effectOwner.GetComponent<CompanionCorruptionStats>().IsDefeated() && !effectOwner.GetComponent<CompanionEffects>().JustRecycled)
		{
			flag = true;
		}
		UnitEffects unitEffects = effectOwner.GetComponent<UnitEffects>();
		unitEffects.IsEffectActive(this);
		if (flag)
		{
			yield break;
		}
		if (useSecondVFXOnActivation)
		{
			if (IsSecondVFXEnabled())
			{
				yield return new WaitForSeconds(delayToVFX);
				PlayEffectActivationSFX();
				SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 5f);
			}
		}
		else if (IsVFXEnabled())
		{
			yield return new WaitForSeconds(delayToVFX);
			PlayEffectActivationSFX();
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
		}
		effectAmount = unitEffects.IsEffectActiveGetAmount(this);
		unitEffects.RemoveEffect(this, activateFeedback: false);
		yield return new WaitForSeconds(delayToDealCorruptPurify);
		List<GameObject> list = currentActiveUnits.GetCurrentActiveUnits();
		for (int i = 0; i < list.Count; i++)
		{
			if (!(list[i] != null))
			{
				continue;
			}
			CorruptionStats component = list[i].GetComponent<CorruptionStats>();
			if (corruptEffect)
			{
				if (!(component is CorruptedAnimalCorruptionStats) || !component.IsDefeated())
				{
					component.Corrupt(effectAmount, null);
				}
				continue;
			}
			if (wave && !waveBenderAchievementData.IsUnlocked() && component is PlayerCorruptionStats && component.IsDefeated())
			{
				waveBenderAchievementData.Unlock();
			}
			component.Purify(effectAmount, null);
		}
		if (battleAction != null)
		{
			battleAction.PlaySFX();
		}
		yield return new WaitForSeconds(radiantBomb ? 0.7f : 0.5f);
		if (wave)
		{
			effectOwner.GetComponent<CorruptedAnimalEffects>().WaveActivated = false;
			ActivateTamedRemorasOmen(effectAmount, effectOwner);
		}
	}

	private void ActivateTamedRemorasOmen(int effectAmount, GameObject effectOwner)
	{
		if (effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			ReferenceSingleton<CellariusOmensHandler>.Instance.ActivateTamedRemorasOmen(effectAmount);
		}
	}
}
